1	// src/lib/rechner/gebaeudestrom.js
2	//
3	// Gebäudestrom-Rechner (Welle 4, Paket GEBAEUDE): PV auf dem Mehrparteien- oder Gewerbegebäude,
4	// Strom an die Einheiten im Haus – DE Mieterstrom (§ 21 Abs. 3 EEG) / Gemeinschaftliche
5	// Gebäudeversorgung (§ 42b EnWG), AT Gemeinschaftliche Erzeugungsanlage (§ 16a ElWOG),
6	// CH ZEV/vZEV (Art. 17–18 EnG). Reine Funktionen ohne React:
7	//
8	//   node src/lib/rechner/gebaeudestrom.js      → Selbsttest
9	//
10	// Methodik (bewusst einfach, OHNE Geldwerte – nur Energiemengen und Anteile):
11	//  - Leistung = Dachfläche / m² je kWp der Dachart (dach.dacharten, wie Dachpacht-Rechner).
12	//  - Erzeugung = kWp × Regionsertrag × Ertragsfaktor der Dachart.
13	//  - Teilnehmender Verbrauch = (Wohneinheiten × Verbrauch je WE + Gewerbeeinheiten × Verbrauch
14	//    je GE) × Teilnahmequote (gebaeudestrom.*, Faktenregister, eigene Einschätzung Klasse C).
15	//  - Im Gebäude genutzt wird nur, was zeitgleich erzeugt UND verbraucht wird: Sättigungskurve
16	//    geteilteMenge() mit der Gleichzeitigkeitsgrenze a je Nutzungsmix – identisch mit dem
17	//    Energy-Sharing-Rechner (MIXE, SPEICHER_PLUS, eigene Näherung, dort dokumentiert).
18	//  - Ergebnis: Eigenverbrauchsanteil (genutzt/Erzeugung), Deckung (genutzt/Verbrauch),
19	//    Überschuss ins Netz – und daraus eine Einordnung, ob die Anlage zum Gebäude passt.
20	//  - Geld (Mieterstromzuschlag, Tarife, Netzentgelte) wird bewusst NICHT gerechnet: Die Werte
21	//    je Land sind noch nicht am Original geprüft (Faktenregister status "zu_pruefen", E6).
22	
23	import { DACH, REGIONEN } from "../invest/markt.js";
24	import { MIXE, SPEICHER_PLUS, geteilteMenge } from "./energySharing.js";
25	import { faktWert } from "../fakten/index.js";
26	
27	const W_WE = faktWert("gebaeudestrom.verbrauchWohneinheit");
28	const W_GE = faktWert("gebaeudestrom.verbrauchGewerbeeinheit");
29	const TEILNAHME = faktWert("gebaeudestrom.teilnahme");
30	export const ANNAHMEN = { W_WE, W_GE, TEILNAHME };
31	
32	/** Länder mit ihren Gebäudestrom-Modellen (Rechtsrahmen: Faktenregister recht.gebaeudestrom.*) */
33	export const LAENDER = [
34	  { id: "de", label: "Deutschland", modelle: [
35	    { id: "mieterstrom", label: "Mieterstrom", sub: "§ 21 Abs. 3 EEG" },
36	    { id: "ggv", label: "Gebäudeversorgung", sub: "§ 42b EnWG" },
37	  ] },
38	  { id: "at", label: "Österreich", modelle: [
39	    { id: "gea", label: "Gemeinschaftliche Erzeugungsanlage", sub: "§ 16a ElWOG" },
40	  ] },
41	  { id: "ch", label: "Schweiz", modelle: [
42	    { id: "zev", label: "ZEV", sub: "Art. 17–18 EnG" },
43	    { id: "vzev", label: "Virtueller ZEV", sub: "Messung durch Netzbetreiber" },
44	  ] },
45	];
46	
47	/** Gebäudetypen → Gleichzeitigkeitsgrenze a aus den Energy-Sharing-Mixen (gleiche Näherung) */
48	const mixA = (id) => MIXE.find((m) => m.id === id)?.a ?? MIXE[1].a;
49	export const GEBAEUDETYPEN = [
50	  { id: "wohn", label: "Wohngebäude", sub: "abends viel Verbrauch", a: mixA("haushalte") },
51	  { id: "gemischt", label: "Wohnen + Gewerbe", sub: "Laden, Büro im Haus", a: mixA("gemischt") },
52	  { id: "gewerbe", label: "Gewerbegebäude", sub: "tagsüber aktiv", a: mixA("gewerbe") },
53	];
54	
55	/** Dacharten: Werte aus dach.dacharten (Faktenregister, wie Dachpacht-Rechner) */
56	const dachart = (id) => DACH.dacharten.find((d) => d.id === id);
57	export const DACHARTEN = [
58	  { id: "geneigt", label: "Geneigtes Dach", sub: "Ziegel, Trapez", m2ProKwp: dachart("trapez").m2ProKwp, ertragFaktor: dachart("trapez").ertragFaktor },
59	  { id: "flach", label: "Flachdach", sub: "Ost/West aufgeständert", m2ProKwp: dachart("flach").m2ProKwp, ertragFaktor: dachart("flach").ertragFaktor },
60	];
61	
62	export const landVon = (id) => LAENDER.find((l) => l.id === id) || LAENDER[0];
63	export const regionenFuer = (id) => REGIONEN.filter((r) => r.land === String(id).toUpperCase());
64	export const dachartVon = (id) => DACHARTEN.find((d) => d.id === id) || DACHARTEN[0];
65	export const gebaeudetypVon = (id) => GEBAEUDETYPEN.find((g) => g.id === id) || GEBAEUDETYPEN[0];
66	
67	export function standardFuer(landId = "de") {
68	  const l = landVon(landId);
69	  const regionen = regionenFuer(l.id);
70	  return {
71	    land: l.id,
72	    modell: l.modelle[0].id,
73	    regionId: (regionen.find((r) => r.id === "de-sued") || regionen[0]).id,
74	    gebaeudetyp: "wohn",
75	    wohneinheiten: 12,
76	    gewerbeeinheiten: 0,
77	    verbrauchWE: W_WE.standard,
78	    verbrauchGE: W_GE.standard,
79	    teilnahme: TEILNAHME.standard,
80	    dachflaecheM2: 120,
81	    dachart: "geneigt",
82	    speicher: false,
83	  };
84	}
85	
86	/**
87	 * Energiebilanz des Gebäudestroms – ohne Geldwerte.
88	 * @returns {{ kwp, erzeugung, verbrauch, genutzt, ueberschuss, eigenverbrauch, deckung, … }}
89	 */
90	export function rechneGebaeudestrom(eingabe = {}) {
91	  const e = { ...standardFuer(eingabe.land || "de"), ...eingabe };
92	  const l = landVon(e.land);
93	  const modell = l.modelle.find((m) => m.id === e.modell) || l.modelle[0];
94	  const region = REGIONEN.find((r) => r.id === e.regionId) || regionenFuer(e.land)[0];
95	  const typ = gebaeudetypVon(e.gebaeudetyp);
96	  const dach = dachartVon(e.dachart);
97	  const a = Math.min(0.9, typ.a + (e.speicher ? SPEICHER_PLUS : 0));
98	
99	  const kwp = e.dachflaecheM2 / dach.m2ProKwp;
100	  const erzeugung = kwp * region.ertrag * dach.ertragFaktor;
101	  const einheiten = e.wohneinheiten + e.gewerbeeinheiten;
102	  const verbrauchGesamt = e.wohneinheiten * e.verbrauchWE + e.gewerbeeinheiten * e.verbrauchGE;
103	  const verbrauch = verbrauchGesamt * e.teilnahme;
104	  const genutzt = geteilteMenge(erzeugung, verbrauch, a);
105	  const ueberschuss = Math.max(0, erzeugung - genutzt);
106	  const eigenverbrauch = erzeugung > 0 ? genutzt / erzeugung : 0;
107	  const deckung = verbrauch > 0 ? genutzt / verbrauch : 0;
108	
109	  // Einordnung: passt die Anlagengröße zum Gebäude? (reine Mengenbetrachtung; Schwellen an der
110	  // Sättigungskurve orientiert – mehr als ~a × Verbrauch kann nie im Haus genutzt werden)
111	  const passung = erzeugung <= 0 || verbrauch <= 0 ? "offen" : eigenverbrauch >= 0.3 ? "passt" : eigenverbrauch >= 0.18 ? "grenzwertig" : "zu_gross";
112	
113	  // Ausgewogene Anlagengröße: größte Anlage, bei der noch rund die Hälfte der Erzeugung im
114	  // Gebäude genutzt wird (Bisektion über kWp; rein informativ, kein Geldwert)
115	  let ausgewogenKwp = 0;
116	  if (verbrauch > 0) {
117	    let lo = 0.5;
118	    let hi = Math.max(kwp, 1);
119	    const evVon = (k) => {
120	      const erz = k * region.ertrag * dach.ertragFaktor;
121	      return erz > 0 ? geteilteMenge(erz, verbrauch, a) / erz : 1;
122	    };
123	    if (evVon(hi) >= 0.5) ausgewogenKwp = hi;
124	    else {
125	      for (let i = 0; i < 40; i++) {
126	        const mitte = (lo + hi) / 2;
127	        if (evVon(mitte) >= 0.5) lo = mitte;
128	        else hi = mitte;
129	      }
130	      ausgewogenKwp = lo;
131	    }
132	  }
133	
134	  return {
135	    eingabe: e,
136	    land: l,
137	    modell,
138	    region,
139	    typ,
140	    dach,
141	    a,
142	    kwp,
143	    erzeugung,
144	    einheiten,
145	    verbrauchGesamt,
146	    verbrauch,
147	    genutzt,
148	    ueberschuss,
149	    eigenverbrauch,
150	    deckung,
151	    genutztJeEinheit: einheiten > 0 ? genutzt / Math.max(1, Math.round(einheiten * e.teilnahme)) : 0,
152	    teilnehmende: Math.max(0, Math.round(einheiten * e.teilnahme)),
153	    passung,
154	    ausgewogenKwp,
155	  };
156	}
157	
158	/* ------------------------------------------------------------------ */
159	/* Selbsttest: node src/lib/rechner/gebaeudestrom.js                   */
160	/* ------------------------------------------------------------------ */
161	
162	export function selbsttest() {
163	  const fehler = [];
164	  const pruefe = (ok, t) => ok || fehler.push(t);
165	
166	  const de = rechneGebaeudestrom({ land: "de" });
167	  pruefe(de.kwp > 0 && de.erzeugung > 0, "DE: Leistung und Erzeugung positiv");
168	  pruefe(de.genutzt <= de.erzeugung + 1e-9 && de.genutzt <= de.verbrauch + 1e-9, "genutzt ≤ Erzeugung und ≤ Verbrauch");
169	  pruefe(Math.abs(de.genutzt + de.ueberschuss - de.erzeugung) < 1e-6, "Bilanz: genutzt + Überschuss = Erzeugung");
170	  pruefe(de.modell.id === "mieterstrom", "DE: Standardmodell Mieterstrom");
171	
172	  const at = rechneGebaeudestrom({ land: "at" });
173	  pruefe(at.region.land === "AT" && at.modell.id === "gea", "AT: Region und Modell GEA");
174	  const ch = rechneGebaeudestrom({ land: "ch", modell: "vzev" });
175	  pruefe(ch.region.land === "CH" && ch.modell.id === "vzev", "CH: Region und Modell vZEV");
176	
177	  const klein = rechneGebaeudestrom({ land: "de", dachflaecheM2: 60 });
178	  pruefe(klein.eigenverbrauch > de.eigenverbrauch, "kleinere Anlage → höherer Eigenverbrauchsanteil");
179	  const gross = rechneGebaeudestrom({ land: "de", dachflaecheM2: 5000, wohneinheiten: 6 });
180	  pruefe(gross.passung === "zu_gross", "sehr große Anlage auf kleinem Gebäude → zu groß");
181	  const sp = rechneGebaeudestrom({ land: "de", speicher: true });
182	  pruefe(sp.genutzt > de.genutzt, "Speicher erhöht den genutzten Anteil");
183	  const gewerbe = rechneGebaeudestrom({ land: "de", gebaeudetyp: "gewerbe", gewerbeeinheiten: 4 });
184	  pruefe(gewerbe.a > de.a, "Gewerbe: höhere Gleichzeitigkeit als Wohnen");
185	  const flach = rechneGebaeudestrom({ land: "de", dachart: "flach" });
186	  pruefe(flach.kwp < de.kwp, "Flachdach: weniger kWp je m² als geneigtes Dach");
187	  pruefe(de.teilnehmende <= de.einheiten, "Teilnehmende ≤ Einheiten");
188	  pruefe(de.ausgewogenKwp > 0, "ausgewogene Größe wird berechnet");
189	  const beiAusgewogen = rechneGebaeudestrom({ land: "de", dachflaecheM2: de.ausgewogenKwp * de.dach.m2ProKwp });
190	  pruefe(Math.abs(beiAusgewogen.eigenverbrauch - 0.5) < 0.02 || beiAusgewogen.eigenverbrauch > 0.5, "bei ausgewogener Größe ≈ 50 % Eigenverbrauch");
191	
192	  return { fehler, beispiel: { de, at, ch } };
193	}
194	
195	if (typeof process !== "undefined" && process.argv?.[1] && /gebaeudestrom\.js$/.test(process.argv[1].replace(/\\/g, "/"))) {
196	  const { fehler, beispiel } = selbsttest();
197	  for (const [k, r] of Object.entries(beispiel))
198	    console.log(
199	      `${k.toUpperCase()}: ${r.kwp.toFixed(0)} kWp, Erzeugung ${(r.erzeugung / 1000).toFixed(1)} MWh, genutzt ${(r.eigenverbrauch * 100).toFixed(0)} %, Deckung ${(r.deckung * 100).toFixed(0)} % (${r.modell.label})`
200	    );
201	  if (fehler.length) {
202	    console.error("FEHLER:\n- " + fehler.join("\n- "));
203	    process.exit(1);
204	  }
205	  console.log("Selbsttest gebaeudestrom.js: alle Prüfungen bestanden.");
206	}
