1	// src/lib/bericht/gebaeudestrom.js – Bericht-Baustein für den Gebäudestrom-Rechner (Welle 4, Paket GEBAEUDE)
2	//
3	// Feldregeln (Positivliste der Eingaben) und Zusammenfassung für die Berichtsseite. Eingebunden in
4	// src/lib/bericht/neuRechnen.js (RECHNER.gebaeudestrom). Rechnet nicht selbst – nur rechneGebaeudestrom().
5	// DE, AT und CH – der Rechner liefert NUR Energiemengen und Anteile, keine Geldwerte (geldwerte: false;
6	// Mieterstromzuschlag, Tarife und Netzentgelte sind noch nicht am Original geprüft, Faktenregister E6).
7	
8	import { PlattformFehler } from "@/lib/plattform/fehler";
9	import { fmt } from "@/lib/rechner/annahmen";
10	import { DACHARTEN, GEBAEUDETYPEN, LAENDER, landVon, rechneGebaeudestrom, regionenFuer, standardFuer } from "@/lib/rechner/gebaeudestrom";
11	import { REGIONEN } from "@/lib/invest/markt";
12	
13	const ids = (liste) => liste.map((x) => x.id);
14	const pct = (x, s = 0) => `${fmt(x * 100, s)} %`;
15	const mwh = (kwh) => `${fmt(kwh / 1000, 1)} MWh`;
16	
17	/** Feldregeln im Format von neuRechnen.js (zahl/wahl/bool werden dort gebaut und übergeben). */
18	export function regelnGebaeudestrom({ zahl, wahl, jaNein }) {
19	  return {
20	    modell: wahl(LAENDER.flatMap((l) => ids(l.modelle))),
21	    regionId: wahl(ids(REGIONEN)),
22	    gebaeudetyp: wahl(ids(GEBAEUDETYPEN)),
23	    wohneinheiten: zahl(0, 500, { ganz: true }),
24	    gewerbeeinheiten: zahl(0, 200, { ganz: true }),
25	    verbrauchWE: zahl(500, 10000),
26	    verbrauchGE: zahl(1000, 200000),
27	    teilnahme: zahl(0.1, 1),
28	    dachflaecheM2: zahl(20, 20000),
29	    dachart: wahl(ids(DACHARTEN)),
30	    speicher: jaNein(),
31	  };
32	}
33	
34	/** Region und Modell müssen zum Land passen. */
35	export function landPruefenGebaeudestrom(e, land) {
36	  const l = landVon(land.toLowerCase());
37	  if (e.regionId && !regionenFuer(l.id).some((r) => r.id === e.regionId)) throw new PlattformFehler(422, "Region und Land passen nicht zusammen.", "eingabe");
38	  if (e.modell && !l.modelle.some((m) => m.id === e.modell)) throw new PlattformFehler(422, "Modell und Land passen nicht zusammen.", "eingabe");
39	}
40	
41	/** Fehlende Felder aus den Landesstandards; Land in Kleinbuchstaben wie im Rechner. */
42	export function normalisierenGebaeudestrom(e, land) {
43	  const basis = standardFuer(land.toLowerCase());
44	  return { ...basis, ...e, land: land.toLowerCase() };
45	}
